const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * that would be applied, in order based on filename (typically numeric prefix).
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Reads migration files from the migrations directory and sorts them
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .filter(file => fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile());

    // Sort files naturally (so migration_001.sql comes before migration_002.sql, etc.)
    sqlFiles.sort((a, b) => {
      return a.localeCompare(b, undefined, {
        numeric: true,
        sensitivity: 'base'
      });
    });

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main function to run the migration logger
 */
function run() {
  console.log('📋 Migration Log');
  console.log('================\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] ${filename}`);
    console.log(`    Path: ${filePath}`);

    // Optionally, read and display the first line of the SQL file as a description
    try {
      const content = fs.readFileSync(filePath, 'utf-8');
      const firstLine = content.split('\n')[0].trim();
      if (firstLine && !firstLine.startsWith('--')) {
        console.log(`    Preview: ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
      } else if (firstLine.startsWith('--')) {
        const comment = firstLine.substring(2).trim();
        console.log(`    Description: ${comment}`);
      }
    } catch (error) {
      console.log(`    Warning: Could not read file contents`);
    }

    console.log('');
  });

  console.log('================');
  console.log(`Total migrations to apply: ${migrationFiles.length}`);
}

// Run the script if called directly
if (require.main === module) {
  run();
}

// Export for testing or module usage
module.exports = {
  getMigrationFiles,
  run,
  MIGRATIONS_DIR
};

-- Add indexes for better performance
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_created_at ON posts(created_at);

