const path = require('path');

/**
 * Database Migration Script
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * that would be applied, in order based on filename (typically numeric prefix).
 * Also reads DATABASE_URL from .env.test for connection configuration.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parses a .env file and returns key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  const envVars = {};

  try {
    if (!fs.existsSync(filePath)) {
      return envVars;
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE or KEY='VALUE' or KEY="VALUE"
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        let [, key, value] = match;
        key = key.trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error parsing .env file: ${error.message}`);
  }

  return envVars;
}

/**
 * Resolves the database connection string
 * Reads DATABASE_URL from .env.test, falls back to environment variable
 * @returns {string|null} The database connection string or null if not found
 */
function resolveConnectionString() {
  // First, check if DATABASE_URL is set in the environment
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // Next, try to read from .env.test file
  const envVars = parseEnvFile(ENV_FILE);

  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  return null;
}

/**
 * Masks sensitive information in a database connection string
 * @param {string} connectionString - The database connection string
 * @returns {string} Masked connection string safe for logging
 */
function maskConnectionString(connectionString) {
  try {
    // Handle postgres://user:pass@host:port/db format
    const urlMatch = connectionString.match(/^(postgres(?:ql)?:\/\/)([^:]+):([^@]+)@(.+)$/);
    if (urlMatch) {
      const [, protocol, user, , host] = urlMatch;
      return `${protocol}${user}:****@${host}`;
    }

    // Handle other formats with password
    const passwordMatch = connectionString.match(/(:\/\/[^:]+):([^@]+)@/);
    if (passwordMatch) {
      return connectionString.replace(passwordMatch[2], '****');
    }

    // If no password detected, return as-is but truncate length
    if (connectionString.length > 50) {
      return connectionString.substring(0, 47) + '...';
    }

    return connectionString;
  } catch (error) {
    return '****';
  }
}

/**
 * Simulates a database connection and logs the result
 * @param {string} connectionString - The database connection string
 * @returns {boolean} True if connection string is valid, false otherwise
 */
function connectToDatabase(connectionString) {
  if (!connectionString) {
    console.error('❌ No database connection string found');
    console.error('   Set DATABASE_URL in .env.test or as an environment variable');
    return false;
  }

  // Validate connection string format
