#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename it would apply, in sorted order.
 * 
 * Migration files should be named with a prefix indicating execution order,
 * such as: 001_initial_schema.sql, 002_add_users_table.sql, etc.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only .sql files
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return [];
  }

  // Sort files alphabetically (this works with numeric prefixes like 001_, 002_, etc.)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('=== Database Migration Script ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration file in order
  migrations.forEach((migration, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, migration);
    const stats = fs.statSync(fullPath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${migration} (${fileSize} KB)`);
  });

  console.log(`\n=== Total: ${migrations.length} migration(s) to apply ===`);
  console.log('\n[Dry run] No migrations were actually applied.');
  console.log('To apply migrations, implement the applyMigration() function.');
}

// Run the script if this file is executed directly
if (require.main === module) {
  runMigrations();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  runMigrations
};

