#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Read SQL migration files from the migrations directory
 * and log each filename in sorted order.
 */
function runMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    console.log('Creating directory...');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    console.log(`Directory '${MIGRATIONS_DIR}' created.`);
    return;
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only SQL files
  const sqlFiles = files.filter(file => {
    return file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile();
  });

  // Sort files alphabetically to ensure consistent ordering
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s) to apply:`);
  console.log('─'.repeat(50));

  // Log each migration file that would be applied
  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('─'.repeat(50));
  console.log('No migrations were actually executed.');
  console.log('Run this script again to preview migration order.');
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations };

