const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted list of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Log migration files that would be applied
 */
function logMigrations() {
  console.log('=== Database Migration Script ===');
  console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((filename, index) => {
    const migrationPath = path.join(MIGRATIONS_DIR, filename);

    // Get file stats for additional info
    try {
      const stats = fs.statSync(migrationPath);
      const fileSize = (stats.size / 1024).toFixed(2);

      console.log(`${index + 1}. ${filename} (${fileSize} KB)`);
    } catch (error) {
      console.log(`${index + 1}. ${filename}`);
    }
  });

  console.log('\n=== End of Migration List ===');
  console.log('These migrations would be applied in the order shown above.');
}

/**
 * Run the migration script
 */
function main() {
  logMigrations();
}

// Execute if run directly
if (require.main === module) {
  main();
}

module.exports = {
  getMigrationFiles,
  logMigrations
