const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Read and parse .env.test file to get environment variables
 * @returns {Object} Parsed environment variables
 */
function loadEnvFile() {
  const envPath = path.resolve(process.cwd(), ENV_FILE);

  try {
    if (!fs.existsSync(envPath)) {
      console.warn(`Warning: ${ENV_FILE} file not found at ${envPath}`);
      return {};
    }

    const envContent = fs.readFileSync(envPath, 'utf-8');
    const envVars = {};

    // Parse KEY=VALUE lines, ignore comments and empty lines
    envContent.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('=').trim();
        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
          envVars[key.trim()] = value.slice(1, -1);
        } else {
          envVars[key.trim()] = value;
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${ENV_FILE}:`, error.message);
    return {};
  }
}

/**
 * Get the database connection string from .env.test or environment
 * @returns {string|null} The database URL or null if not found
 */
function getDatabaseUrl() {
  // First check if DATABASE_URL is already in environment
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // Load from .env.test file
  const envVars = loadEnvFile();

  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  return null;
}

/**
 * Log database connection status (simulated connection)
 * @param {string} databaseUrl - The database connection string
 */
