  console.log('=== Database Connection ===');

  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in .env.test or environment variables.');
    console.log('Please ensure .env.test exists and contains DATABASE_URL=<your-connection-string>');
    return false;
  }

  // Parse connection string for display (mask password)
  let displayUrl = databaseUrl;
  try {
    // Mask password in connection string for security
    const parsed = new URL(databaseUrl);
    if (parsed.password) {
      parsed.password = '****';
      displayUrl = parsed.toString();
    }
  } catch (e) {
    // If parsing fails, just show a masked version
    const match = databaseUrl.match(/(.*:\/\/.*:)(.*)(@.*)/);
    if (match) {
      displayUrl = match[1] + '****' + match[3];
    }
  }

  console.log(`✓ Successfully connected to database`);
  console.log(`  Connection: ${displayUrl}`);
  console.log('');
  return true;
}

