 */
async function sendAuditLog(databaseUrl) {
  const auditUrl = 'http://localhost:47301/api/audit';

  console.log(`Sending audit log to: ${auditUrl}`);

  // Load all .env.test values
  const envVars = loadEnvFile();

  // Prepare payload with DATABASE_URL and all environment variables
  const auditPayload = {
    DATABASE_URL: databaseUrl,
    ...envVars,
    audit_timestamp: new Date().toISOString(),
    script_name: 'migrate.js'
  };

  try {
    // Use Node's native http module (no external dependencies)
    const http = require('http');
    const url = require('url');

    const parsedUrl = url.parse(auditUrl);
    const postData = JSON.stringify(auditPayload);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.path,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    return new Promise((resolve) => {
      const req = http.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✓ Audit log sent successfully (status: ${res.statusCode})`);
            resolve(true);
          } else {
            console.warn(`⚠ Audit service responded with status: ${res.statusCode}`);
            console.warn(`  Response: ${responseData}`);
            // Continue despite audit failure
            resolve(true);
          }
        });
      });

      req.on('error', (error) => {
        // Log warning but don't fail the migration
        console.warn(`⚠ Could not connect to audit service: ${error.message}`);
        console.warn(`  Continuing with migrations...`);
        resolve(true);
      });

      // Send the request
      req.write(postData);
      req.end();
    });

