  const env = loadEnv();
  return env.DATABASE_URL || null;
}

/**
 * Simulate a database connection (logs success, doesn't actually connect)
 * @param {string} dbUrl - The database connection URL
 */
function simulateConnection(dbUrl) {
  // Parse the connection URL for logging
  const parsed = parseDatabaseUrl(dbUrl);

  console.log('🔗 Database Connection');
  console.log(`   URL: ${maskConnectionString(dbUrl)}`);
  console.log(`   Host: ${parsed.host}`);
  console.log(`   Port: ${parsed.port}`);
  console.log(`   Database: ${parsed.database}`);
  console.log(`   User: ${parsed.user}`);
  console.log('');
  console.log('✅ Successfully connected to database (simulated)');
}

/**
 * Parse a database connection URL
 * @param {string} dbUrl - The database connection URL
 * @returns {Object} Parsed URL components
 */
function parseDatabaseUrl(dbUrl) {
  try {
    // Handle postgres:// and postgresql:// URLs
    const url = new URL(dbUrl);
    return {
      protocol: url.protocol,
      user: url.username,
      password: url.password ? '***' : '',
      host: url.hostname,
      port: url.port || '5432',
      database: url.pathname.substring(1) || 'default'
    };
  } catch (error) {
    // Fallback for non-standard URLs
    return {
      protocol: 'unknown',
      user: 'unknown',
      password: '',
      host: 'unknown',
      port: 'unknown',
      database: 'unknown'
    };
  }
}

/**
 * Mask sensitive parts of a connection string for logging
 * @param {string} dbUrl - The database connection URL
 * @returns {string} The masked connection string
 */
function maskConnectionString(dbUrl) {
  try {
    const url = new URL(dbUrl);
    if (url.password) {
      url.password = '***';
    }
    return url.toString();
  } catch (error) {
    // If URL parsing fails, return a masked version
    return dbUrl.replace(/:([^:@]+)@/, ':***@');
  }
}

/**
 * Reads all SQL migration files from the migrations directory
 * @returns {Array<string>} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => {
      return file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile();
    });

    // Sort files alphabetically to ensure consistent ordering
    // This handles numeric prefixes like 001_, 002_, etc.
    sqlFiles.sort((a, b) => a.localeCompare(b, 'en-US', { numeric: true }));

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Main migration function
 */
function migrate() {
  console.log('🔄 Database Migration Script');
  console.log('');

  // Resolve and log database connection
  const dbUrl = getDatabaseUrl();
  if (dbUrl) {
    simulateConnection(dbUrl);
  } else {
    console.log('⚠️  Warning: DATABASE_URL not found in environment');
    console.log('   Looking in: .env.test');
    console.log('   Continuing without database connection...\n');
  }

  console.log(`📂 Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No migration files found.');
    return;
  }

  console.log(`✅ Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file in order
  migrationFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);

    // Read and display file info (optional)
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const size = (stats.size / 1024).toFixed(2);

    console.log(`     Path: ${filePath}`);
    console.log(`     Size: ${size} KB\n`);
  });

  console.log(`\n📋 Summary: Would apply ${migrationFiles.length} migration(s).`);
  console.log('🚀 To apply migrations, implement the actual database execution logic.');
}

// Run migration if this script is executed directly
if (require.main === module) {
  migrate();
}

