#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Load environment variables from a .env file
 * @param {string} filePath - Path to the .env file
 */
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  lines.forEach(line => {
    // Skip comments and empty lines
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE format
    const match = trimmedLine.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      // Remove quotes if present
      const unquotedValue = value.replace(/^(['"])(.*)\1$/, '$2');
      process.env[key] = unquotedValue;
    }
  });
}

/**
 * Resolve the database connection string from environment variables
 * @returns {string|null} The DATABASE_URL or null if not set
 */
function resolveConnectionString() {
  // Load .env.test file
  const envTestPath = path.join(__dirname, '.env.test');
  loadEnvFile(envTestPath);

  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    return null;
  }

  // Mask sensitive information in the connection string for logging
  const maskedUrl = dbUrl.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@');
  return maskedUrl;
}

/**
 * Log database connection status
 */
function logConnectionStatus() {
  const dbUrl = resolveConnectionString();

  if (!dbUrl) {
    console.warn('⚠ Warning: DATABASE_URL not found in .env.test');
    console.log('  Migrations would run without a database connection.\n');
    return false;
  }

  console.log('✓ Database connection string resolved');
  console.log(`  Connection: ${dbUrl}\n`);
  console.log('✓ Successfully connected to database (simulated)\n');
  return true;
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted list of migration files
 */
function getMigrationFiles() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Error: migrations directory does not exist');
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for .sql files
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(migrationsDir, file)).isFile()
  );

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return [];
  }

  // Sort files alphabetically to ensure consistent ordering
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration Runner ===\n');

  // Resolve and log database connection
  const hasConnection = logConnectionStatus();

