  console.log('Scanning for migrations...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('\n✓ Migration plan complete (no migrations to apply)');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`  [${index + 1}] ${file}`);
  });

  console.log('\n--- Migration Order ---');
  console.log('The following migrations would be applied in this order:\n');

  migrationFiles.forEach((file, index) => {
    const fullPath = path.join(__dirname, 'migrations', file);
    const stats = fs.statSync(fullPath);
    console.log(`${index + 1}. ${file} (${stats.size} bytes)`);
  });

  console.log('\n✓ Migration plan complete');
}

// Run the migration
if (require.main === module) {
  migrate();
}

module.exports = { getMigrationFiles, migrate, resolveConnectionString, logConnectionStatus };

