#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename that would be applied in order.
 * 
 * Migration files should be named with a numeric prefix to ensure proper ordering,
 * such as: 001_initial_schema.sql, 002_add_users_table.sql, etc.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Array of migration file paths
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files.filter(file => {
    // Only include files ending with .sql
    return file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile();
  });

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return [];
  }

  // Sort files alphabetically (this will work with numeric prefixes like 001_, 002_, etc.)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function migrate() {
  console.log('🔄 Database Migration Script');
  console.log('='.repeat(50));
  console.log(`Scanning migrations directory: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('\n✅ Nothing to migrate.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file in order
  migrationFiles.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(fullPath);

    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${fullPath}`);
    console.log(`   Size: ${stats.size} bytes`);

    // Optionally read and log the first line of the SQL file
    try {
      const content = fs.readFileSync(fullPath, 'utf8');
      const firstLine = content.split('\n')[0].trim();
      if (firstLine && !firstLine.startsWith('--')) {
        console.log(`   Preview: ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
      }
    } catch (err) {
      console.log(`   Warning: Could not read file content`);
    }

    console.log('');
  });

  console.log('='.repeat(50));
  console.log(`\n✅ Would apply ${migrationFiles.length} migration(s) in the order listed above.`);
  console.log('   (No actual changes were made - this is a dry run)\n');
}

// Run the migration
if (require.main === module) {
  migrate();
}

// Export for testing purposes
module.exports = {
  getMigrationFiles,
  migrate
};

