#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations/';

function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files (case insensitive)
  const sqlFiles = files.filter(file => 
    fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile() &&
    file.toLowerCase().endsWith('.sql')
  );

  // Sort filenames alphabetically to ensure consistent ordering
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  return sqlFiles;
}

function runMigrations() {
  console.log('🔄 Checking for migrations...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('✅ No migration files found in ./migrations/');
    return;
  }

  console.log(`📋 Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
  });

  console.log(`\n✨ Would apply ${migrationFiles.length} migration(s) in total.`);
}

// Run the migration script
if (require.main === module) {
  runMigrations();
}

module.exports = { getMigrationFiles, runMigrations };

