const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';

/**
 * Parse a .env file and return an object of key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const envContent = fs.readFileSync(filePath, 'utf-8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip comments and empty lines
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE, handling quotes
    const match = trimmedLine.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Resolve the DATABASE_URL connection string from .env.test
 */
function getDatabaseUrl() {
  // Check if .env.test exists
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`⚠️  Warning: '${ENV_FILE}' file not found.`);
    return null;
  }

  const env = parseEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.warn(`⚠️  Warning: DATABASE_URL not found in '${ENV_FILE}'.`);
