const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them alphabetically
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

function getMigrationOrder(files) {
  // Sort by typical migration numbering patterns:
  // 1. Extract numbers from filenames (e.g., 001_initial.sql, 002_users.sql)
  // 2. If no numeric prefix, fall back to alphabetical order

  return files.sort((a, b) => {
    // Try to extract leading numbers
    const aMatch = a.match(/^(\d+)/);
    const bMatch = b.match(/^(\d+)/);

    if (aMatch && bMatch) {
      // Both have numeric prefixes - compare numerically
      return parseInt(aMatch[1], 10) - parseInt(bMatch[1], 10);
    } else if (aMatch) {
      // Only a has numeric prefix - it comes first
      return -1;
    } else if (bMatch) {
      // Only b has numeric prefix - it comes first
      return 1;
    } else {
      // No numeric prefixes - compare alphabetically
      return a.localeCompare(b);
    }
  });
}

function logMigrations() {
  console.log('🔄 Checking for migrations...\n');

  const migrationFiles = getMigrationFiles();
  const orderedFiles = getMigrationOrder(migrationFiles);

  if (orderedFiles.length === 0) {
    console.log('✅ No migration files found in ./migrations/');
    return;
  }

  console.log(`📋 Found ${orderedFiles.length} migration file(s):\n`);

  orderedFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const status = stats.size > 0 ? '✓' : '⚠';

    console.log(`  [${index + 1}] ${status} ${file}`);
  });

  console.log(`\n📝 Migrations that would be applied (in order):`);
  console.log('─'.repeat(50));
  orderedFiles.forEach(file => {
    console.log(`  → ${file}`);
