  try {
    const url = new URL(databaseUrl);
    return {
      protocol: url.protocol,
      host: url.hostname,
      port: url.port,
      database: url.pathname.substring(1),
      username: url.username || 'redacted',
      // Password never included - security measure
      hasCredentials: !!(url.username || url.password)
    };
