#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * that would be applied, in alphabetical order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files.filter(file => 
      fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile() &&
      file.endsWith('.sql')
    );

    // Sort files alphabetically (which also sorts them numerically for numbered prefixes)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

function logMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`  [${index + 1}] ${file}`);
  });

  console.log(`\nWould apply ${migrationFiles.length} migration(s).`);
}

// Run the migration logger
if (require.main === module) {
  logMigrations();
}

module.exports = { getMigrationFiles, logMigrations };

{
  "name": "migration-script",
  "version": "1.0.0",
  "description": "Database migration script that reads SQL files from ./migrations/ directory",
  "scripts": {
    "migrate": "node migrate.js"
  }
}

